    # Task demonstrations indicate three large rectangular patches, one in
    # each of three independent regions. Enumerate solid rectangles and retain
    # those of at least 4x5 cells, then merge overlapping subrectangles.
    candidates = set()
    for top in range(h):
        for bottom in range(top + 3, h):
            height = bottom - top + 1
            col = 0
            while col < w:
                color = grid[top][col]
                if any(grid[r][col] != color for r in range(top, bottom + 1)):
                    col += 1
                    continue
                left = col
                col += 1
                while col < w and all(grid[r][col] == color for r in range(top, bottom + 1)):
                    col += 1
                right = col
                width = right - left
                if height * width >= 20 and height >= 4 and width >= 4:
                    candidates.add((top, bottom + 1, left, right, color))
    # A maximal candidate is any qualifying rectangle that cannot be
    # extended as a solid same-color rectangle in any direction.
    rectangles = []
    for t, b, l, r, color in candidates:
        extend_up = t > 0 and all(grid[t-1][c] == color for c in range(l, r))
        extend_down = b < h and all(grid[b][c] == color for c in range(l, r))
        extend_left = l > 0 and all(grid[y][l-1] == color for y in range(t, b))
        extend_right = r < w and all(grid[y][r] == color for y in range(t, b))
        if not (extend_up or extend_down or extend_left or extend_right):
            rectangles.append((t, b, l, r))
    out = [row[:] for row in grid]
    for t, b, l, r in rectangles:
        for y in range(t, b):
            for x in range(l, r):
                out[y][x] = 4
    return out
